import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';

import { MotionDemo, Page, Ramp, Section, SemanticColourGroups, ShadowGrid, TokenTable, TypeScale } from './FoundationDoc';
import { groupBy, modeOf, select, tokens, valueIn } from './tokens';

const meta = {
  title: 'Foundations',
  parameters: { layout: 'fullscreen' },
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

const count = (collection: string) => tokens.filter((t) => t.collection === collection).length;

export const Overview: Story = {
  render: (_, { globals }) => (
    <Page
      title="Foundations"
      lede="Design tokens exported from the Figma file “Design system AI”. Components use these CSS variables only — never raw values."
    >
      <Section title="How tokens are layered">
        <TokenTable
          mode={modeOf(globals)}
          tokens={[
            { css: '--color-brand-600', collection: 'primitives.color', name: 'Primitive · raw value, never used in components', type: 'C', values: { [modeOf(globals)]: 'e.g. #4f46e5' } },
            { css: '--interactive-bg-primary-default', collection: 'semantic.color', name: 'Semantic · intent, aliases a primitive', type: 'C', values: { [modeOf(globals)]: 'var(--color-brand-600)' } },
          ]}
        />
      </Section>
      <Section
        title="Modes"
        note="Use the Theme and Project buttons in the toolbar. In an app, set data-theme and data-project on the same element (normally <html>)."
      >
        <TokenTable
          mode={modeOf(globals)}
          tokens={[
            { css: 'data-theme', collection: '', name: 'light · dark — semantic.color', type: 'S', values: { [modeOf(globals)]: String(globals.theme) } },
            { css: 'data-project', collection: '', name: 'project-a · project-b — primitives.color (Project B is a placeholder brand)', type: 'S', values: { [modeOf(globals)]: String(globals.project) } },
          ]}
        />
      </Section>
      <Section title="Inventory">
        <TokenTable
          mode={modeOf(globals)}
          tokens={['primitives.color', 'primitives.dimension', 'primitives.radius', 'primitives.typography', 'primitives.motion', 'primitives.opacity', 'primitives.number', 'semantic.color', 'semantic.dimension', 'semantic.radius', 'semantic.typography', 'semantic.motion', 'semantic.opacity', 'effects'].map((c) => ({
            css: c,
            collection: c,
            name: c,
            type: 'F',
            values: { [modeOf(globals)]: `${count(c)} tokens` },
          }))}
        />
      </Section>
    </Page>
  ),
  play: async ({ canvasElement, globals }) => {
    // Proves tokens.css and the fonts loaded: body uses surface/bg/default (gray/50 light, gray/950 dark) and Inter.
    const body = getComputedStyle(canvasElement.ownerDocument.body);
    await expect(body.backgroundColor).toBe(globals.theme === 'dark' ? 'rgb(3, 7, 18)' : 'rgb(249, 250, 251)');
    await expect(body.fontFamily).toContain('Inter');
  },
};

export const Colour: Story = {
  render: (_, { globals }) => {
    const mode = modeOf(globals);
    const ramps = groupBy(select('primitives.color'), 1);
    return (
      <Page title="Colour" lede="Primitive ramps hold raw values; components only use the semantic tokens below them.">
        {[...ramps].map(([ramp, list]) => (
          <Section key={ramp} title={`Primitive · ${ramp}`}>
            <Ramp tokens={list} mode={mode} />
          </Section>
        ))}
        <SemanticColourGroups mode={mode} />
      </Page>
    );
  },
  play: async ({ canvasElement, globals }) => {
    // Primary action colour resolves through semantic → primitive to the exported Figma value
    // for the active mode (Project A light: brand/600 #4f46e5).
    const token = tokens.find((t) => t.css === '--interactive-bg-primary-default')!;
    const hex = valueIn(token, modeOf(globals));
    const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
    const chip = canvasElement.querySelector('[data-token="--interactive-bg-primary-default"] td div');
    await expect(chip).not.toBeNull();
    await expect(getComputedStyle(chip!).backgroundColor).toBe(`rgb(${r}, ${g}, ${b})`);
  },
};

export const Typography: Story = {
  render: (_, { globals }) => (
    <Page title="Typography" lede="17 text styles. Apply them with the .text-<role> classes, or the --text-style-* variables inside a CSS module.">
      <Section title="Type scale">
        <TypeScale mode={modeOf(globals)} />
      </Section>
      <Section title="Primitives">
        <TokenTable tokens={select('primitives.typography')} mode={modeOf(globals)} />
      </Section>
    </Page>
  ),
};

export const SpacingAndSize: Story = {
  name: 'Spacing & Size',
  render: (_, { globals }) => {
    const mode = modeOf(globals);
    const groups = groupBy(select('semantic.dimension'), 2);
    return (
      <Page title="Spacing & Size" lede="A strict 4px grid. Inline = horizontal gaps, stack = vertical gaps, inset = padding.">
        {[...groups].map(([group, list]) => (
          <Section key={group} title={group}>
            <TokenTable tokens={list} mode={mode} preview="width" />
          </Section>
        ))}
        <Section title="Primitive sizes">
          <TokenTable tokens={select('primitives.dimension')} mode={mode} preview="width" />
        </Section>
      </Page>
    );
  },
};

export const Radius: Story = {
  render: (_, { globals }) => (
    <Page title="Radius" lede="Use the role tokens (control, surface, overlay, badge) in components; the scale is for exceptions.">
      <Section title="Roles">
        <TokenTable tokens={select('semantic.radius')} mode={modeOf(globals)} preview="radius" />
      </Section>
      <Section title="Scale">
        <TokenTable tokens={select('primitives.radius')} mode={modeOf(globals)} preview="radius" />
      </Section>
    </Page>
  ),
};

export const Elevation: Story = {
  render: (_, { globals }) => (
    <Page title="Elevation" lede="Light theme uses drop shadows; dark theme swaps elevation/* for a 1px border glow (no dark drop shadows).">
      <Section title="Elevation roles">
        <ShadowGrid tokens={select('effects', 'elevation/').filter((t) => !t.name.includes('/dark/'))} mode={modeOf(globals)} />
      </Section>
      <Section title="Shadow scale">
        <ShadowGrid tokens={select('effects', 'shadow/')} mode={modeOf(globals)} />
      </Section>
    </Page>
  ),
};

export const Motion: Story = {
  render: (_, { globals }) => (
    <Page title="Motion" lede="Durations and easings. Animations are disabled when the user prefers reduced motion.">
      <Section title="Try it">
        <MotionDemo durations={select('primitives.motion', 'motion/duration/')} easings={select('primitives.motion', 'motion/easing/')} />
      </Section>
      <Section title="Tokens">
        <TokenTable tokens={[...select('semantic.motion'), ...select('primitives.motion')]} mode={modeOf(globals)} />
      </Section>
    </Page>
  ),
};

export const OpacityAndZIndex: Story = {
  name: 'Opacity & Z-index',
  render: (_, { globals }) => (
    <Page title="Opacity & Z-index" lede="Stacking order for layered UI, and opacity roles.">
      <Section title="Z-index">
        <TokenTable tokens={select('primitives.number', 'z-index/')} mode={modeOf(globals)} />
      </Section>
      <Section title="Opacity">
        <TokenTable tokens={[...select('semantic.opacity'), ...select('primitives.opacity')]} mode={modeOf(globals)} />
      </Section>
      <Section title="Stroke width & breakpoints">
        <TokenTable tokens={[...select('semantic.dimension', 'stroke-width/'), ...select('primitives.number', 'stroke-width/'), ...select('primitives.number', 'breakpoint/')]} mode={modeOf(globals)} />
      </Section>
    </Page>
  ),
};

