    const [error, setError] = useState('');

    return (
        <Switch
            size="md"
            showInnerContent
            disabled={false}
            label="Sync calendar"
            checked={on}
            loading={loading}
            helperText={error || 'Every second request fails, so the switch stays where it was.'}
            onCheckedChange={(next) => {
              setLoading(true);
              setError('');
              setTimeout(() => {
                setLoading(false);
                setAttempts((n) => n + 1);
                if (attempts % 2 === 1) setError('Couldn’t reach the calendar service. Try again.');
                else setOn(next);
              }, 800);
            }} />
    );
};

