import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, within } from 'storybook/test';

import { Avatar } from '../Avatar/Avatar';
import { Badge } from '../Badge/Badge';
import { OverflowMenu } from '../MenuButton/MenuButton';
import { ProgressBar } from '../ProgressBar/ProgressBar';
import { Switch } from '../Switch/Switch';
import { EditableCell, Table, type TableColumn } from './Table';

interface Project {
  id: string;
  name: string;
  owner: string;
  status: 'Active' | 'Paused' | 'Archived';
  progress: number;
  budget: number;
  public: boolean;
}

const DATA: Project[] = [
  { id: 'p1', name: 'Website redesign', owner: 'Alex Johnson', status: 'Active', progress: 72, budget: 48000, public: true },
  { id: 'p2', name: 'Mobile app', owner: 'Sam Lee', status: 'Active', progress: 35, budget: 120000, public: false },
  { id: 'p3', name: 'Brand refresh', owner: 'Riya Patel', status: 'Paused', progress: 10, budget: 22000, public: false },
  { id: 'p4', name: 'Design tokens', owner: 'Chen Wu', status: 'Active', progress: 95, budget: 9000, public: true },
  { id: 'p5', name: 'Help centre', owner: 'Maria Garcia', status: 'Archived', progress: 100, budget: 15000, public: true },
];

const STATUS = { Active: 'success', Paused: 'warning', Archived: 'neutral' } as const;
const money = (n: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(n);

const COLUMNS: TableColumn<Project>[] = [
  { key: 'name', header: 'Project', sortable: true },
  {
    key: 'owner',
    header: 'Owner',
    sortable: true,
    render: (r) => (
      <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
        <Avatar name={r.owner} size="sm" aria-hidden role={undefined} aria-label={undefined} />
        {r.owner}
      </span>
    ),
  },
  { key: 'status', header: 'Status', render: (r) => <Badge label={r.status} status={STATUS[r.status]} size="sm" /> },
  { key: 'progress', header: 'Progress', sortable: true, width: 160, render: (r) => <ProgressBar label={`${r.name} progress`} hideLabel value={r.progress} size="sm" helperText={`${r.progress}%`} layout="inline" /> },
  { key: 'budget', header: 'Budget', align: 'right', sortable: true, headerIcon: { name: 'status/info', position: 'trailing', label: 'Approved budget in USD' }, render: (r) => money(r.budget) },
  { key: 'actions', header: 'Actions', align: 'center', width: 64, render: (r) => <OverflowMenu label={`Actions for ${r.name}`} size="sm" items={[{ id: 'open', label: 'Open' }, { id: 'dup', label: 'Duplicate' }, { type: 'divider' }, { id: 'del', label: 'Delete', danger: true }]} /> },
];

const meta = {
  title: 'Components/Table',
  component: Table<Project>,
  tags: ['autodocs'],
  args: { caption: 'Projects', columns: COLUMNS, rows: DATA, size: 'md' },
  argTypes: { columns: { control: false }, rows: { control: false } },
} satisfies Meta<typeof Table<Project>>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvas, userEvent }) => {
    const budget = canvas.getByRole('columnheader', { name: /Budget/ });
    await userEvent.click(within(budget).getByRole('button'));
    await expect(budget).toHaveAttribute('aria-sort', 'ascending');
    const firstRow = canvas.getAllByRole('row')[1];
    await expect(firstRow).toHaveTextContent('Design tokens');
  },
};

export const Selectable: Story = {
  args: { selectable: true },
  play: async ({ canvas, userEvent }) => {
    await userEvent.click(canvas.getByRole('checkbox', { name: 'Select row p2' }));
    await expect(canvas.getByRole('checkbox', { name: 'Select all rows' })).toHaveProperty('indeterminate', true);
    await userEvent.click(canvas.getByRole('checkbox', { name: 'Select all rows' }));
    await expect(canvas.getByRole('checkbox', { name: 'Select row p5' })).toBeChecked();
  },
};

export const Expandable: Story = {
  args: { renderExpanded: (r: Project) => <p>{r.name} is owned by {r.owner}. Budget {money(r.budget)}, {r.progress}% complete.</p> },
};

export const Sizes: Story = {
  render: (args) => (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-stack-lg)' }}>
      <Table {...args} size="sm" caption="Small (32px rows)" rows={DATA.slice(0, 2)} />
      <Table {...args} size="md" caption="Medium (40px rows)" rows={DATA.slice(0, 2)} />
      <Table {...args} size="lg" caption="Large (48px rows)" rows={DATA.slice(0, 2)} />
    </div>
  ),
};

export const EditableCells: Story = {
  render: () => {
    const [rows, setRows] = useState(DATA);
    const update = (id: string, patch: Partial<Project>) => setRows((all) => all.map((r) => (r.id === id ? { ...r, ...patch } : r)));
    return (
      <Table
        caption="Budgets (click a value to edit)"
        rows={rows}
        columns={[
          { key: 'name', header: 'Project' },
          {
            key: 'budget',
            header: 'Budget',
            align: 'right',
            render: (r) => (
              <EditableCell
                label={`Budget for ${r.name}`}
                type="number"
                value={String(r.budget)}
                validate={(v) => (Number(v) > 0 ? null : 'Must be greater than 0')}
                onCommit={(v) => update(r.id, { budget: Number(v) })}
              />
            ),
          },
          { key: 'public', header: 'Public', align: 'center', render: (r) => <Switch size="sm" aria-label={`${r.name} is public`} checked={r.public} onCheckedChange={(on) => update(r.id, { public: on })} /> },
        ]}
      />
    );
  },
};

export const StickyHeader: Story = { args: { stickyHeader: true, maxHeight: 220, rows: [...DATA, ...DATA.map((r) => ({ ...r, id: `${r.id}b` }))] } };

export const Loading: Story = { args: { loading: true } };

export const Empty: Story = { args: { rows: [], empty: 'No projects match your filters.' } };

