import { useRef, useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor, within } from 'storybook/test';

import {
  Alert,
  AppBar,
  Avatar,
  AvatarGroup,
  AvatarIdentity,
  Badge,
  Breadcrumb,
  Button,
  Card,
  ComboButton,
  EmptyState,
  Modal,
  Navbar,
  OverflowMenu,
  Pagination,
  ProgressBar,
  Select,
  Table,
  Tabs,
  TextInput,
  ToastProvider,
  useToast,
  type NavEntry,
  type TableColumn,
} from '../index';

interface Task {
  id: string;
  title: string;
  assignee: string;
  status: 'To do' | 'In progress' | 'Done';
  due: string;
}

const NAV: NavEntry[] = [
  { key: 'home', label: 'Dashboard', icon: 'nav/home' },
  { key: 'projects', label: 'Projects', icon: 'layout/grid' },
  { key: 'tasks', label: 'Tasks', icon: 'form/check' },
  { key: 'team', label: 'Team', icon: 'user/group' },
  { key: 'settings', label: 'Settings', icon: 'action/settings' },
];

const TASKS: Task[] = [
  { id: 't1', title: 'Export colour tokens', assignee: 'Chen Wu', status: 'Done', due: '2026-10-02' },
  { id: 't2', title: 'Build Button component', assignee: 'Alex Johnson', status: 'Done', due: '2026-10-09' },
  { id: 't3', title: 'Dark mode QA', assignee: 'Riya Patel', status: 'In progress', due: '2026-10-28' },
  { id: 't4', title: 'Date picker keyboard support', assignee: 'Sam Lee', status: 'In progress', due: '2026-10-30' },
  { id: 't5', title: 'Project B brand colours', assignee: 'Maria Garcia', status: 'To do', due: '2026-11-06' },
];

const STATUS = { 'To do': 'neutral', 'In progress': 'info', Done: 'success' } as const;

function Dashboard() {
  const toast = useToast();
  const scrollRef = useRef<HTMLDivElement>(null);
  const [nav, setNav] = useState('projects');
  const [collapsed, setCollapsed] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [tasks, setTasks] = useState(TASKS);
  const [draft, setDraft] = useState({ title: '', assignee: '' });

  const columns: TableColumn<Task>[] = [
    { key: 'title', header: 'Task', sortable: true },
    {
      key: 'assignee',
      header: 'Assignee',
      sortable: true,
      render: (t) => (
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
          <Avatar name={t.assignee} size="sm" aria-hidden role={undefined} aria-label={undefined} />
          {t.assignee}
        </span>
      ),
    },
    { key: 'status', header: 'Status', render: (t) => <Badge label={t.status} status={STATUS[t.status]} size="sm" /> },
    { key: 'due', header: 'Due', align: 'right', sortable: true },
    {
      key: 'menu',
      header: 'Actions',
      align: 'center',
      width: 64,
      render: (t) => (
        <OverflowMenu
          size="sm"
          label={`Actions for ${t.title}`}
          items={[
            { id: 'done', label: 'Mark done', icon: 'form/check', onSelect: () => setTasks((all) => all.map((x) => (x.id === t.id ? { ...x, status: 'Done' } : x))) },
            { type: 'divider' },
            { id: 'del', label: 'Delete', icon: 'action/delete', danger: true, onSelect: () => setTasks((all) => all.filter((x) => x.id !== t.id)) },
          ]}
        />
      ),
    },
  ];

  const done = tasks.filter((t) => t.status === 'Done').length;

  return (
    <div style={{ display: 'flex', height: '100vh', background: 'var(--surface-bg-default)' }}>
      <Navbar
        items={NAV}
        selectedKey={nav}
        onSelect={setNav}
        collapsed={collapsed}
        onCollapsedChange={setCollapsed}
        header={<strong className="text-heading-sm">Acme</strong>}
        footer={collapsed ? <Avatar name="Alex Johnson" size="sm" /> : <AvatarIdentity name="Alex Johnson" email="alex@acme.com" size="sm" />}
      />
      <div ref={scrollRef} style={{ flex: 1, minWidth: 0, overflow: 'auto' }}>
        <AppBar
          headline="Design system"
          supportingText="Project · 5 members"
          elevation="on-scroll"
          scrollContainer={scrollRef}
          actions={[
            { icon: 'action/search', label: 'Search', onClick: () => {} },
            { icon: 'feedback/bell', label: 'Notifications', onClick: () => {} },
          ]}
        />
        <main style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-stack-lg)', padding: 'var(--space-inset-lg) var(--space-inset-xl)' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--space-inline-md)', flexWrap: 'wrap' }}>
            <Breadcrumb items={[{ label: 'Projects', href: '#' }, { label: 'Design system' }]} />
            <div style={{ display: 'flex', gap: 'var(--space-inline-sm)', alignItems: 'center' }}>
              <AvatarGroup max={3} aria-label="Members">
                {TASKS.map((t) => (
                  <Avatar key={t.id} name={t.assignee} size="sm" />
                ))}
              </AvatarGroup>
              <ComboButton
                label="New task"
                icon="action/add"
                onClick={() => setModalOpen(true)}
                items={[
                  { id: 'import', label: 'Import from CSV', icon: 'action/upload' },
                  { id: 'template', label: 'Use a template', icon: 'action/copy' },
                ]}
              />
            </div>
          </div>

          <Alert sentiment="warning" title="Project B brand colours are placeholders" description="Contrast hasn’t been re-checked for Project B — don’t ship it until real colours land." onClose={() => {}} />

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: 'var(--space-inline-lg)' }}>
            <Card variant="outlined" headingLevel={2} caption="Progress" headline={`${done} of ${tasks.length} tasks done`}>
              <ProgressBar label="Project progress" hideLabel value={(done / Math.max(1, tasks.length)) * 100} size="sm" />
            </Card>
            <Card variant="outlined" headingLevel={2} caption="Components" headline="42 in Storybook" badges={<Badge label="+42" status="success" size="sm" />} body="Every component ships with stories, docs and accessibility checks." />
            <Card variant="outlined" headingLevel={2} caption="Tokens" headline="449 variables" body="Exported from Figma, light and dark, Project A and B." />
          </div>

          <Tabs
            aria-label="Project sections"
            items={[
              {
                value: 'tasks',
                label: 'Tasks',
                content: (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-stack-md)' }}>
                    <Table caption="Tasks" hideCaption columns={columns} rows={tasks} selectable empty={<EmptyState kind="cleared" title="No tasks" size="sm" />} />
                    <Pagination total={tasks.length} pageSize={10} showTotal showSizeChanger={false} />
                  </div>
                ),
              },
              { value: 'files', label: 'Files', content: <EmptyState kind="first-use" title="No files yet" description="Upload specs, exports and screenshots." primaryAction={<Button leadingIcon="action/upload">Upload files</Button>} /> },
              { value: 'activity', label: 'Activity', content: <p>Activity feed.</p> },
            ]}
          />
        </main>
      </div>

      <Modal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        title="New task"
        primaryLabel="Create task"
        onPrimary={() => {
          if (!draft.title) return;
          setTasks((all) => [...all, { id: `t${Date.now()}`, title: draft.title, assignee: draft.assignee || 'Alex Johnson', status: 'To do', due: '2026-11-20' }]);
          setModalOpen(false);
          setDraft({ title: '', assignee: '' });
          toast({ status: 'success', title: 'Task created', children: draft.title });
        }}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-stack-md)' }}>
          <TextInput label="Title" required value={draft.title} onChange={(e) => setDraft((d) => ({ ...d, title: e.target.value }))} />
          <Select
            label="Assignee"
            value={draft.assignee || null}
            onValueChange={(v) => setDraft((d) => ({ ...d, assignee: v ?? '' }))}
            options={Array.from(new Set(TASKS.map((t) => t.assignee))).map((n) => ({ value: n, label: n }))}
          />
        </div>
      </Modal>
    </div>
  );
}

const meta = {
  title: 'Examples/Project dashboard',
  parameters: { layout: 'fullscreen' },
  render: () => (
    <ToastProvider>
      <Dashboard />
    </ToastProvider>
  ),
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvas, canvasElement, userEvent }) => {
    // End-to-end: open the modal, pick an assignee from a Select inside it, create a task.
    await userEvent.click(canvas.getByRole('button', { name: 'New task' }));
    const body = within(canvasElement.ownerDocument.body);
    const dialog = await body.findByRole('dialog', { name: 'New task' });
    // Wait for showModal() to move focus into the dialog before typing.
    await waitFor(() => expect(dialog.contains(dialog.ownerDocument.activeElement)).toBe(true));
    const title = within(dialog).getByRole('textbox', { name: /Title/ });
    await userEvent.click(title);
    // paste (one input event) rather than type: per-key caret tracking is unreliable when the preview window lacks OS focus.
    await userEvent.paste('Write release notes');
    await expect(title).toHaveValue('Write release notes');
    await userEvent.click(within(dialog).getByRole('combobox', { name: /Assignee/ }));
    await userEvent.click(await body.findByRole('option', { name: 'Sam Lee' }));
    await userEvent.click(within(dialog).getByRole('button', { name: 'Create task' }));
    await waitFor(() => expect(canvas.getByRole('rowheader', { name: 'Write release notes' })).toBeVisible());
  },
};

